assert all(accepted[v['questionId']]==v['cardCanonicalSha256'] for v in reg['cards'])
files=[p for p in D.rglob('*') if p.is_file()];assert not any(p.is_symlink() for p in files)
for p in files:assert p.read_bytes()==g('show',head+':'+str(p.relative_to(C))),str(p)
assert set(g('ls-tree','-r','--name-only',head,'--',str(D.relative_to(C))).decode().splitlines())=={str(p.relative_to(C)) for p in files}
